// biome-ignore-all format: Generated by scripts/build-ai-references.ts from the capability contracts.
export const references: Record<string, string> = {
	"ai": "// App-facing text generation and foreground delegation. Both use the host-selected backend.\n\nexport interface AiCapability {\n\trunAgent(input: {\n\t\trequestId: string\n\t\tprompt: string\n\t}): Promise<{ text: string } | { cancelled: true }>\n\tcancelAgent(input: { requestId: string }): Promise<boolean>\n\n\tgenerateText(input: {\n\t\tsystem?: string\n\t\tprompt: string\n\t\t// Opt into a host-owned, purpose-scoped context projection. The host reads\n\t\t// trusted user knowledge and prepends a prompt-safe fragment; the app never\n\t\t// sees the projection or the composed system prompt. `'learning'` requires the\n\t\t// `context:learning` scope. A typed union, never an arbitrary string — a new\n\t\t// value is added only alongside its own scope and privacy policy.\n\t\tcontext?: 'learning'\n\t\ttemperature?: number\n\t\tmaxTokens?: number\n\t}): Promise<{ text: string }>\n}\n",
	"calendar": "// App-facing Calendar capability contract.\n\nexport interface CalendarEvent {\n\tid: string\n\ttitle: string\n\tstartsAt: number\n\tendsAt: number\n\tlocation?: string\n\taccountId?: string\n}\n\nexport interface CalendarCapability {\n\tlistToday(input: { timezone: string; accountId?: string; now?: number }): Promise<CalendarEvent[]>\n}\n",
	"devkit": "// App-facing devkit capability contract. The one privileged platform surface\n// app-code uses: compile a draft, run it in a scoped preview kernel embedded in\n// the caller's own window, and ship it.\n//\n// A devkit project is a directory in the caller's own data dir: source under\n// `projects/<slug>/src` and an optional `icon` file beside it. The caller only\n// ever names the project by `slug`; devkit reads the tree off disk itself, so\n// no file bytes cross the worker boundary. Every method is serializable in and\n// out — the app exchanges a slug and receives ids / diagnostics / zip bytes.\n\nimport type { CheckResult, CompileResult } from './toolchain.ts'\n\n// Host-owned preview presentation. The Mac host returns a URL that app-code embeds in its\n// preview slot; Frieren opens the preview in its own OS window (`kind: 'window'`)\n// so every app — the preview included — renders in the same sandboxed frame.\nexport type DevkitPreview = { kind: 'url'; src: string } | { kind: 'window' }\n\nexport interface DevkitCapability {\n\t// ── toolchain (server / backend) ───────────────────────────────────────────\n\t// Bundle the named project, returning the structured `CompileResult`\n\t// (outputs + diagnostics). The host reads the source tree itself; the caller\n\t// only names the project.\n\tcompile(input: { slug: string }): Promise<CompileResult>\n\t// Type-check the named project, returning diagnostics only. Degrades to\n\t// CAPABILITY_UNAVAILABLE on hosts without a type checker (browser).\n\ttypecheck(input: { slug: string }): Promise<CheckResult>\n\n\t// ── preview (client, browser only) ──────────────────────────────────────\n\t// Compile the named project + (re)mount it into the caller's preview slots.\n\t// On a compile error, `diagnostics` is non-empty and the last-good preview\n\t// stays mounted. `reset` wipes the draft's persisted state first, for a\n\t// clean boot (⟳ Run/Restart); omit it to keep state across rebuilds.\n\trun(input: {\n\t\tslug: string\n\t\treset?: boolean\n\t}): Promise<{ previewId: string; diagnostics: string[]; preview?: DevkitPreview }>\n\t// Tear down a running preview.\n\tstop(input: { previewId: string }): Promise<void>\n\t// Promote the named project to the real `/applications` as a standalone app.\n\t// Compiles fresh and rejects a colliding id (check-first guard) — install only\n\t// creates, never overwrites. The project's `icon`, if any, is bundled so the\n\t// app shows its icon in the launcher. Returns the installed id.\n\tinstall(input: { slug: string }): Promise<{ id: string }>\n\t// Compile and emit a `.zip` of the bundle (`manifest.json` + `app.js` +\n\t// `gui.js` + optional `icon`), importable through the launcher's existing zip\n\t// path.\n\tpack(input: { slug: string }): Promise<{ zip: Uint8Array }>\n}\n",
	"email": "// App-facing Email capability contract. No Cloudflare imports, no provider\n// clients. Host wiring (broker, Fastmail/Gmail adapters) lives in Frieren.\n\nexport interface EmailSummary {\n\tid: string\n\tfrom: string\n\tsubject: string\n\treceivedAt: number\n\tunread: boolean\n\t// Stamped by the host when results are aggregated across accounts, so the app\n\t// can route a later `readDetail`/`markRead` back to the right account.\n\taccountId?: string\n}\n\nexport interface EmailDetail extends EmailSummary {\n\tbodyText: string\n}\n\nexport interface EmailCapability {\n\tlistUnread(input: { since?: number; limit?: number; accountId?: string }): Promise<EmailSummary[]>\n\treadDetail(input: {\n\t\tid: string\n\t\taccountId?: string\n\t\tpurpose: 'briefing-detail' | 'summarization'\n\t}): Promise<EmailDetail>\n\tmarkRead(input: { id: string; accountId?: string }): Promise<{ success: true }>\n}\n",
	"image": "// The `image` capability is the image-side sibling of `ai` — a single USE facet\n// any app may call. It is its own capability (not a verb on `ai`) because text and\n// image are separate engines with separate models everywhere underneath (pi-ai keeps\n// parallel `Models`/`ImagesModels` stacks), and a provider backs each independently.\n// Resolution follows the active AI account: if its provider has no image binding,\n// the capability is unavailable.\n\nimport { defineCapability } from '../core.ts'\n\n// USE facet — exposed to every app via `@justfiles/app/capabilities/image`.\nexport interface GeneratedImage {\n\t// Base64-encoded bytes (pi-ai's ImageContent shape). Callers that keep images\n\t// around (e.g. the agent's image tool) should offload to the Volume, not store this.\n\tdata: string\n\tmimeType: string\n}\n\nexport interface ImageCapability {\n\tgenerateImage(input: { prompt: string }): Promise<{ images: GeneratedImage[] }>\n}\n\n// The factory lives here (not index.ts) so agent.ts can import it without a\n// module cycle. The metadata is the contract's runtime twin: `implementTool`\n// derives the agent tool's schema and description from it.\nexport const image = defineCapability<'image', ImageCapability>('image', {\n\tgenerateImage: {\n\t\tdescription:\n\t\t\t'Generate an image from a text prompt and save it to the user’s files. ' +\n\t\t\t'Returns the saved file path(s). Use when the user asks you to draw, create, ' +\n\t\t\t'or show them an image of something.',\n\t\tinput: {\n\t\t\ttype: 'object',\n\t\t\tproperties: {\n\t\t\t\tprompt: {\n\t\t\t\t\ttype: 'string',\n\t\t\t\t\tdescription: 'What the image should depict — subject, style, mood.'\n\t\t\t\t}\n\t\t\t},\n\t\t\trequired: ['prompt']\n\t\t}\n\t}\n})\n",
	"reader": "export interface ReaderCapability {\n\tread(input: { url: string }): Promise<{\n\t\turl: string\n\t\ttitle: string\n\t\tmarkdown: string\n\t\tsiteName?: string\n\t\tbyline?: string\n\t\tpublishedAt?: number\n\t\twordCount: number\n\t}>\n\topen(input: { url: string }): Promise<void>\n}\n",
	"volume": "export interface Volume {\n\t// --- metadata ---\n\n\t/**\n\t * Stat a path, following symlinks.\n\t * Throws ENOENT if the path does not exist.\n\t */\n\tstat(path: string): Promise<Stat>\n\n\t/**\n\t * Stat a path without following the final symlink component.\n\t * Useful for inspecting symlinks themselves.\n\t */\n\tlstat(path: string): Promise<Stat>\n\n\t/** Returns true if the path exists (any file type). Never throws. */\n\texists(path: string): Promise<boolean>\n\n\t/** Read a single xattr from a path, following the final symlink. */\n\tgetXattr(path: string, name: string): Promise<Uint8Array | null>\n\n\t/** Write or replace a single xattr on a path, following the final symlink. */\n\tsetXattr(path: string, name: string, value: Uint8Array): Promise<void>\n\n\t/** List all xattr names currently set on a path. */\n\tlistXattr(path: string): Promise<string[]>\n\n\t/** Remove a single xattr from a path. */\n\tremoveXattr(path: string, name: string): Promise<void>\n\n\t// --- file I/O ---\n\n\t/**\n\t * Read the entire contents of a file into memory.\n\t * Throws ENOENT if the file does not exist.\n\t * Throws EISDIR if the path is a directory.\n\t */\n\treadFile(path: string): Promise<Uint8Array>\n\n\t/**\n\t * Write (create or overwrite) a file.\n\t * Parent directory must exist.\n\t * Throws ENOENT if a parent directory is missing.\n\t * Throws EISDIR if the path refers to a directory.\n\t *\n\t * A CREATE is ATOMIC: the path does not exist, and then it exists holding exactly\n\t * `data`. A concurrent reader never resolves it and finds a prefix (#324) — the\n\t * bytes and the name commit as one fact, so a reader needs no retry, no deadline\n\t * and no way to tell \"still being written\" from \"corrupt\". It cannot have one: the\n\t * intermediate states a torn writer exposes are not enumerable from the reader's\n\t * side, and the last of them (a prefix that happens to parse) is silent.\n\t *\n\t * An OVERWRITE is NOT atomic, deliberately. Making it atomic means publishing a\n\t * new inode under the same name, which churns everything keyed by inode (the\n\t * native backend's path map, `metaCache`, and `watch`'s change feed) and defeats\n\t * `putBlob`'s check that the inode it opened is still the\n\t * one the name points at. So a reader concurrent with an overwrite observes the\n\t * old bytes or the new ones, and on a backend that fills in place (native) a torn\n\t * state in between — the same as POSIX, and as Node's `fs.writeFile`. Order it, or\n\t * write to a fresh name and `rename`.\n\t *\n\t * Atomicity here is about VISIBILITY, not durability: nothing is fsynced.\n\t *\n\t * Moves the file's `mtimeNs`/`ctimeNs` to now, so mtime means \"when these bytes\n\t * last changed\" and an app can sort by recency. A write with an imported timestamp\n\t * keeps that time because it is the same edit, not a new one. Directory\n\t * mtime is NOT maintained — no caller reads it.\n\t *\n\t * `exclusive` and `update` are the two ends of one question — what must be true of\n\t * the path before these bytes land — and this call is the only place it can be\n\t * asked without a gap, because it is the call that resolves the path.\n\t *\n\t * With `exclusive: true` this is a CREATE, not a write: it throws EEXIST if the\n\t * path is already taken. That makes it a *claim* on a name rather than a probe —\n\t * `exists()` followed by `writeFile` is a TOCTOU, and the loser of the race has\n\t * its file overwritten. The check, the create and the content are one operation in\n\t * the backend (`atomicCreate`: `O_EXCL` + `link`, a single IndexedDB transaction, a\n\t * synchronous map check), so concurrent writers are decided by the storage and the\n\t * loser can read the winner back immediately. A backend without that capability\n\t * falls back to a best-effort pre-check.\n\t *\n\t * With `update: true` it is an EDIT, not a create: ENOENT if nothing is there\n\t * (`open` without `O_CREAT`). A plain write brings a file into being, and with it\n\t * every missing parent folder — so a caller holding a path that has since been\n\t * moved or deleted silently *recreates* the tree it remembers instead of failing.\n\t * An editor autosaving to the note it has open wants this: the write is where the\n\t * path is proven still real, so it cannot be stale by the time the bytes land.\n\t *\n\t * With `ifHash`, the write lands only while the path still holds that content.\n\t * `null` means the path must still be absent. A mismatch throws ESTALE. This\n\t * makes a read, compute, write cycle safe against another writer without a lock.\n\t */\n\twriteFile(\n\t\tpath: string,\n\t\tdata: Uint8Array,\n\t\topts?: { exclusive?: boolean; update?: boolean; ifHash?: string | null }\n\t): Promise<void>\n\n\t/**\n\t * Append data to a file, creating it if it does not exist.\n\t * Parent directory must exist.\n\t */\n\tappendFile(path: string, data: Uint8Array): Promise<void>\n\n\t// --- directory operations ---\n\n\t/**\n\t * Create a directory.\n\t * With recursive: silently succeeds if the directory already exists and\n\t * creates all missing parent directories.\n\t * Without recursive (default): throws EEXIST if the path exists, throws\n\t * ENOENT if a parent is missing.\n\t */\n\tmkdir(path: string, opts?: { recursive?: boolean; mode?: number }): Promise<void>\n\n\t/**\n\t * List the contents of a directory.\n\t * Returns one Dirent per entry (name + type + ino).\n\t * Throws ENOENT if the directory does not exist.\n\t * Throws ENOTDIR if the path is not a directory.\n\t */\n\treaddir(path: string): Promise<Dirent[]>\n\n\t// --- removal ---\n\n\t/**\n\t * Remove a file, symlink, or directory.\n\t * - recursive: remove non-empty directories (like rm -r).\n\t * - force: silently succeed if the path does not exist (like rm -f).\n\t * Throws ENOTEMPTY if the path is a non-empty directory and recursive is\n\t * not set.\n\t */\n\trm(path: string, opts?: { recursive?: boolean; force?: boolean }): Promise<void>\n\n\t// --- move and copy ---\n\n\t/**\n\t * Move or rename a file, symlink, or directory.\n\t * If newPath already exists it is replaced atomically (POSIX rename\n\t * semantics). Throws ENOENT if oldPath does not exist.\n\t *\n\t * There is NO exclusive form, and that is a decision about where a guarantee can live\n\t * rather than an omission. POSIX `rename` replaces, and no atomic no-replace rename is\n\t * reachable from Node (`renameat2(RENAME_NOREPLACE)` and `renamex_np(RENAME_EXCL)` are\n\t * not bound), so on a real filesystem \"refuse a taken destination\" could only ever be a\n\t * check before the act. `writeFile`'s `exclusive` is different in KIND: `O_EXCL` is a\n\t * primitive every backend already has, so there the check IS the operation.\n\t *\n\t * Offering the flag anyway would mean a promise whose strength varied by backend —\n\t * settled by one store's transaction, guessed at by a filesystem — and a call site\n\t * cannot reason about that. So claiming a name is the CALLER's policy, held in one\n\t * place, which is what every system in this position does: git takes a lock it owns\n\t * (`index.lock`, `O_CREAT|O_EXCL`), Maildir gives files names that cannot collide, dpkg\n\t * writes `.dpkg-tmp` and moves it. Here it is app-notes' `claimPath` — order the claims,\n\t * check the destination, number up on EEXIST (its DESIGN.md §1b records why).\n\t *\n\t * What the model owes REGARDLESS is not corrupting the tree while replacing: a name is\n\t * `(parent, name)` on a row, so a displaced row is tombstoned and the row that took its\n\t * name is a separate write in the same commit — a name that survives the move still\n\t * resolves.\n\t */\n\trename(oldPath: string, newPath: string): Promise<void>\n\n\t/**\n\t * Copy a file or directory.\n\t * - recursive: required when src is a directory; copies the entire subtree.\n\t * If dest already exists it is overwritten for files; for directories the\n\t * contents are merged.\n\t * Throws EISDIR / ENOTDIR on type mismatches.\n\t */\n\tcp(src: string, dest: string, opts?: { recursive?: boolean }): Promise<void>\n\n\t// --- symlinks ---\n\n\t/**\n\t * Create a symbolic link at path pointing to target.\n\t * Argument order mirrors POSIX ln -s: symlink(target, path).\n\t * Throws EEXIST if path already exists.\n\t */\n\tsymlink(target: string, path: string): Promise<void>\n\n\t/**\n\t * Read the raw target string of a symbolic link.\n\t * Throws ENOENT if path does not exist.\n\t * Throws EINVAL if path is not a symlink.\n\t */\n\treadlink(path: string): Promise<string>\n\n\t// --- permissions and timestamps ---\n\n\t/**\n\t * Change the permission mode bits of a file or directory.\n\t * Follows symlinks (acts on the target, not the link itself).\n\t */\n\tchmod(path: string, mode: number): Promise<void>\n\n\t/**\n\t * Set the modification time of a file or directory.\n\t * Expressed in nanoseconds since the Unix epoch.\n\t * Useful for preserving mtimes when syncing or copying.\n\t */\n\tutimes(path: string, mtimeNs: bigint): Promise<void>\n\n\t// --- tree walking ---\n\n\t/**\n\t * Walk the subtree rooted at path, calling visitor once per node\n\t * (including the root itself).\n\t *\n\t * Directories are visited before their contents. Paths passed to the\n\t * visitor are absolute and normalised.\n\t *\n\t * One paged `children` per directory, which is what `readdir` costs too — the\n\t * seam has no whole-subtree read, and a walk that asked for one would be\n\t * reading rows a mount boundary makes not ours to read.\n\t *\n\t * Throws ENOENT if path does not exist.\n\t */\n\tscan(path: string, visitor: (path: string, stat: Stat) => Promise<void>): Promise<void>\n\n\t/**\n\t * Watch a single path for changes — an inotify-style primitive.\n\t *\n\t * The listener fires after a change to the path commits, coalesced per\n\t * microtask (one logical write = several storage ops = one event). Like\n\t * real inotify it tracks both the resolved inode (content/meta edits) AND\n\t * the parent dentry, so a delete+recreate or rename/replace that rebinds\n\t * the path to a fresh inode still fires (and the next event re-resolves).\n\t *\n\t * The event carries the `source` the write was tagged with, so callers can\n\t * ignore their own writes. The path need not exist yet — once a dentry binds it,\n\t * the watch picks it up.\n\t *\n\t * With `{ recursive: true }` the watch instead reports STRUCTURAL changes\n\t * — entries created/removed/renamed — at or under `path`, plus a rebind of\n\t * `path` itself or of any ancestor (which takes the whole subtree with it);\n\t * pair it with a `scan` of the same path to rebuild the listing. Content/meta\n\t * edits to existing files do NOT fire — watch the concrete file for those. That\n\t * also holds when another writer updates a path that already exists: it is an\n\t * edit, not structure. This is the\n\t * substrate for a directory browser's auto-refresh.\n\t *\n\t * A recursive delivery is a WAKE, not a log: it says the listing is stale and\n\t * carries no per-change detail, so events are coalesced into at most one delivery\n\t * per `WATCH_BURST_MS` with a guaranteed trailing one. A bulk operation therefore\n\t * wakes a consumer a bounded number of times, not once per entry.\n\t *\n\t * Synthesized from the store's own order: `subscribe` where a store pushes,\n\t * a `since` poll on the same window where it does not. Either way it always\n\t * delivers. Returns a promise of the unsubscribe.\n\t */\n\twatch(\n\t\tpath: string,\n\t\tlistener: (event: WatchEvent) => void,\n\t\topts?: { recursive?: boolean }\n\t): Promise<() => void>\n}\n// App-facing Volume capability contract. Scoped filesystem access; the host\n// owns the path-to-storage mapping. The requested `scopes` decide which\n// volume is bound: `'app'` (or missing) is the per-app chroot, `'system'`\n// is the user's root volume, and a path-like scope binds a prefix chroot.\n\nimport type { Volume } from '@justfiles/fs'\nimport type { Stream } from '../core.ts'\n\nexport interface VolumeEntry {\n\tpath: string\n\ttype: 'file' | 'dir'\n\t// Modification time in ns since the epoch, as a `number` (a `bigint` cannot\n\t// cross the seam). Present on a RECURSIVE scan only — the tree walk already\n\t// holds each entry's stat, so carrying it saves the caller an N+1 `stat` storm\n\t// just to sort by recency. `readdir` (the non-recursive scan) has no mtime.\n\tmtimeNs?: number\n}\n\n// The capability surface IS the host filesystem interface — reused verbatim, not\n// re-declared. Multi-arg and optional-arg signatures flow straight through the\n// capability seam now (`writeFile(path, data)`, `mkdir(path, opts?)`,\n// `setXattr(path, name, value)`, …). The two methods Volume models with a\n// CALLBACK are the exceptions, since a function cannot cross the seam:\n//   - `scan(path, visitor)` → re-expressed as a one-shot that RETURNS the listing\n//   - `watch(path, listener)` → a `Stream` (see `VolumeStreams` below)\n// Note: `stat`/`lstat`/`utimes` carry `bigint` and reads carry `Uint8Array`,\n// neither of which survives a JSON wire — so volume binds as a LOCAL capability.\nexport type VolumeCapability = Omit<Volume, 'watch' | 'scan' | 'writeFile'> & {\n\tscan(input: { path: string; recursive?: boolean }): Promise<VolumeEntry[]>\n\t// The one place the capability ADDS to `Volume`, because the addition is the host's\n\t// and not the filesystem's: the host creates missing parent directories for a write,\n\t// which apps rely on. `parents: false` declines it, so a write into a folder that has\n\t// since been deleted or renamed fails ENOENT instead of quietly rebuilding it — the\n\t// only way to check \"is that folder still there\" without a gap, since the check is\n\t// then the write itself.\n\twriteFile(\n\t\tpath: string,\n\t\tdata: Uint8Array,\n\t\topts?: { exclusive?: boolean; update?: boolean; parents?: boolean }\n\t): Promise<void>\n}\n\n// Payload delivered to a `volume.watch` subscriber. `source` is the tag the\n// triggering write carried (sync tags remote-applied pulls; local user writes\n// carry none), so an app can ignore its own writes.\nexport interface WatchEvent {\n\tsource?: string\n}\n\n// Streams the volume can drive into a subscribing app (Part D). `watch` is a\n// SINGLE-PATH watch: it fires when the file at `path` is itself changed\n// (content/metadata) or created/removed/renamed. It is NOT recursive — writes\n// to children of a watched directory do not fire, so watch a concrete file\n// (e.g. the open document), not a folder. The app declares it via\n// `subscriptions(state)` and folds events with `t.fromEvent('volume', 'watch')`.\n//\n// `recursive: true` flips it to a STRUCTURAL change signal for the subtree at\n// `path`: it fires whenever an entry is created/removed/renamed there — or when\n// the subtree itself is moved out from under you — coalesced. The substrate for a\n// directory browser's auto-refresh (pair it with a recursive `scan` of the same\n// path to rebuild the listing). Content edits to existing files don't fire; watch\n// the open file for those. The signal is scoped to the volume the app's scopes\n// bound, so a chrooted app never wakes on writes outside its prefix.\nexport interface VolumeStreams {\n\twatch(input: { path: string; recursive?: boolean }): Stream<WatchEvent>\n}\n",
	"notify": "import { defineCapability } from '../core.ts'\nimport type { Notification } from './types.ts'\n\nexport type { Channel, Notification, Route } from './types.ts'\n\n// What an app passes to `notify`: everything but `source`, which the kernel stamps\n// from the calling app's trusted identity (apps can't spoof another's source).\nexport type NotifyInput = Omit<Notification, 'source'>\n\nexport interface NotifyCapability {\n\tnotify(input: NotifyInput): void\n}\n\n// The `notify` capability. An app emits a Notification; the host projects it onto\n// its platform channel. Declared with no scope — emitting is unprivileged, and the\n// kernel-stamped `source` is the only trust the channel needs.\nexport const notify = defineCapability<'notify', NotifyCapability>('notify')\n\n// The portable notification shape — one type shared by the agent, the `notify`\n// capability, and every host channel. A notification is a TRANSIENT projection (a\n// ping over a platform-specific channel), not a store: case-1 durability already\n// lives in the agent transcript. Grown per slice (CLAUDE.md): Phase 2 adds\n// `durable?`, `scheduledAt?`, `actions[]` — not before their slice.\n\nexport interface Notification {\n\tid: string\n\t// Who produced it: 'agent' | <appId> | 'system'. The kernel STAMPS this for\n\t// sandboxed apps (an app can't spoof another's identity); trusted producers\n\t// (agent, cron) set it directly. Click-routing keys off it.\n\tsource: string\n\tkind: 'info' | 'error' | 'question' // grows: 'progress' | 'reminder' (Phase 2)\n\ttitle: string\n\tbody: string\n\t// Coalesce/replace key → the channel's native dedup id (macOS request\n\t// identifier; web Notification `tag`), so a re-post under the same thread\n\t// replaces the previous banner instead of stacking.\n\tthreadId?: string\n\troute?: Route // where a click goes\n}\n\nexport type Route =\n\t| { kind: 'chat' } // summon the host's chat surface\n\t| { kind: 'app'; id: string } // open a mini-app\n\t| { kind: 'settings'; pane?: string } // e.g. accounts → reconnect\n\n// A host channel: it projects a notification onto its platform — the Mac host broadcasts\n// to its launcher sockets (→ UNUserNotificationCenter); frieren pushes to the\n// browser (web push / in-tab toast). Everything portable lives ABOVE it; the\n// channel is the one per-host piece.\nexport type Channel = (notification: Notification) => void\n"
}
